-- Biology Ch12: Genetics and Evolution — BATCH 4 (Evolution: natural selection, modes, speciation, patterns)
-- Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'Genetics and Evolution' AND subtopic IN ('Natural Selection & Fitness', 'Modes of Selection', 'Speciation & Isolation', 'Evolutionary Patterns');

-- Q1 [Natural Selection & Fitness] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Natural Selection & Fitness', 'In a population of marine fish, a single female releases hundreds of thousands of eggs each spawning season, yet the habitat can sustain only a small fraction of the resulting young to maturity. Within Darwin''s framework of natural selection, this overproduction of offspring relative to available resources directly establishes which condition in each generation?', '[{"label": "A", "text": "Random change in allele frequencies"}, {"label": "B", "text": "Competition among individuals for limited resources"}, {"label": "C", "text": "Generation of new alleles by mutation"}, {"label": "D", "text": "Measurement of fitness relative to the population"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because Darwin reasoned that more offspring are produced than can survive, so resources for survival and reproduction are limited; as the textbook states, ''The capacity for reproduction in all organisms outstrips the availability of resources to support their numbers. Thus, there is competition for those resources in each generation'' (lines 21694-21698). Overproduction relative to resources is the tenet that sets up this struggle, and only the individuals with inherited variations that best compete will survive and have more offspring (lines 21699-21701). (Choice A) Random change in allele frequencies describes genetic drift, which the textbook defines as ''simply the effect of chance...not due to an advantage conferred by some genetically-encoded trait'' (lines 22956-22958), a non-selective process distinct from the resource competition overproduction creates. (Choice B) is correct: overproduction beyond what resources can support produces competition for those limited resources in each generation. (Choice C) Generation of new alleles by mutation is the ultimate source of new genetic variation (lines 21767-21768), but it is the origin of the variation selection acts on, not the condition that overproduction establishes. (Choice D) Relative fitness is how an individual''s reproductive contribution compares ''to the other organisms in the population'' (lines 23158-23160), a downstream measure of selection''s outcome rather than the condition overproduction directly creates. This is a Knowledge of Scientific Concepts and Principles question because you must recall Darwin''s tenet that the overproduction of offspring relative to limited resources produces competition within each generation.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', NULL FROM q;

-- Q2 [Natural Selection & Fitness] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Natural Selection & Fitness', 'A hospital lab treats a large bacterial culture with an antibiotic, and over successive generations the proportion of resistant cells rises sharply. Regarding the resistance allele responsible, the most defensible account of its origin is that it', '[{"label": "A", "text": "was induced by exposure to the antibiotic"}, {"label": "B", "text": "spread by chance rather than by survival"}, {"label": "C", "text": "was already present at low frequency"}, {"label": "D", "text": "was newly created by directional selection"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because the variation that natural selection acts on is already present in a population and does not arise in response to an environmental change; the textbook states that applying antibiotics selects for resistant bacteria, but "the gene for resistance was already present in the bacteria''s gene pool, likely at a low frequency," and that "mutations for antibiotic resistance do not arise as a result of antibiotic application" (OpenStax Biology 2e, lines 21996-22005). The antibiotic does not generate the allele; it merely kills non-resistant cells, so the pre-existing resistant minority survives and divides, raising the allele''s frequency. This illustrates that natural selection can only "select—it cannot create" novel variation (line 22708). (Choice A) is incorrect: the resistance "did not arise by mutation because of applying the antibiotic," so exposure does not induce the allele—this is the Lamarckian induced-variation misconception the passage explicitly refutes (lines 22001-22005). (Choice B) is incorrect: spreading "by chance rather than by survival" describes genetic drift, "simply the effect of chance" and "not due to an advantage conferred by some genetically-encoded trait" (lines 22956-22959); here the increase is driven by differential survival of resistant cells, which is selection, not drift. (Choice C) is correct: the allele "was already present in the bacteria''s gene pool, likely at a low frequency" before exposure (lines 22001-22002). (Choice D) is incorrect: directional selection shifts phenotype frequencies when the environment changes (line 23178), but selection "cannot create" new alleles—mutation, not selection, is the source of novel variation (lines 22707-22709). This is a Scientific Reasoning and Problem Solving question because you must apply the principle that selection acts on pre-existing variation to a described antibiotic-resistance scenario and rule out induced-mutation and chance-based accounts.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
  UNION ALL
