-- Q4 [Natural Selection & Fitness] medium skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Natural Selection & Fitness', 'A field biologist is comparing several lizards in a single population and wants to rank them by evolutionary (Darwinian) fitness. Which individual would most likely be assigned the highest fitness?', '[{"label": "A", "text": "The individual that lives the longest"}, {"label": "B", "text": "The physically strongest individual"}, {"label": "C", "text": "A long survivor leaving few offspring"}, {"label": "D", "text": "The one leaving the most surviving offspring"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because evolutionary (Darwinian) fitness is defined as an individual''s ability to survive and reproduce, measured by its relative contribution of offspring to the next generation''s gene pool. The textbook states that natural selection ''selects for individuals with greater contributions to the gene pool of the next generation'' and ''Scientists call this an organism''s evolutionary (Darwinian) fitness'' (p. 505); relative fitness allows researchers ''to determine which individuals are contributing additional offspring to the next generation.'' Thus the individual leaving the most surviving (reproductively viable) offspring relative to the rest of the population has the highest fitness. (Choice A) is incorrect: longevity alone is not fitness, because the text notes an individual may survive yet ''will not pass to the next generation'' its alleles if it leaves no offspring, so a long life that yields no reproduction confers no fitness. (Choice B) is incorrect: strength is only a trait that, via sexual selection, may help ''bigger, stronger'' males ''obtain the vast majority of the total matings,'' but fitness is measured by the resulting reproductive success, not by strength itself. (Choice C) is incorrect: surviving well while leaving few offspring gives low fitness, since ''it is not an individual''s absolute fitness that counts'' but the number of offspring contributed relative to others. (Choice D) is correct: it captures relative reproductive success, the ''capacity of the members to produce more reproductively viable offspring relative to others.'' This is a Knowledge of Scientific Concepts and Principles question because you must recall the textbook definition of evolutionary fitness as relative reproductive success.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 95)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', NULL FROM q
