-- Q6 [Natural Selection & Fitness] medium skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Natural Selection & Fitness', 'A biology instructor is explaining why Darwin and Wallace, despite proposing natural selection, could not account for how favorable variation was passed to offspring, and how the modern synthesis (Neo-Darwinism) of the 1940s resolved this gap. Which of the following statements about the modern synthesis is accurate?

I. It integrated Mendelian (particulate) genetics with natural selection, supplying the mechanism of heredity that Darwin and Wallace had lacked.
II. It established blending inheritance as the genetic basis for the heritable variation on which natural selection acts.
III. It identified genetic drift as the non-random, fitness-based force that drives adaptation.', '[{"label": "A", "text": "I only"}, {"label": "B", "text": "III only"}, {"label": "C", "text": "I and III only"}, {"label": "D", "text": "II and III only"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because only statement I correctly describes the modern synthesis. OpenStax states that Darwin and Wallace developed natural selection without understanding the mechanisms of inheritance, and that ''over the next few decades scientists integrated genetics and evolution in what became known as the modern synthesis—the coherent understanding of the relationship between natural selection and genetics that took shape by the 1940s'' (lines 22720, 22734-22736). Mendel''s rediscovered ''particulate nature of genes'' (line 22732) provided the heredity mechanism that the earlier, incorrect ''blending inheritance'' theory could not (lines 22726-22727). (Choice A) is correct: statement I alone captures that the synthesis merged Mendelian particulate genetics with natural selection to supply the missing hereditary mechanism, while statements II and III are both false. (Choice B) is wrong because statement III misassigns adaptation to genetic drift, which OpenStax defines as the ''effect of chance on a population''s gene pool'' (line 23389)—a random, non-selective force, not a fitness-based one. (Choice C) is wrong because it pairs the true statement I with the false statement III. (Choice D) is wrong because statement II reverses the history: blending inheritance was the ''predominant (and incorrect) genetic theory'' that obstructed understanding of natural selection (lines 22726-22727), not the basis the synthesis established; statement III remains false as well. This is a Knowledge of Scientific Concepts and Principles question because you must recall how the modern synthesis reconciled Mendelian heredity with Darwinian natural selection and distinguish that fitness-based, non-random process from random genetic drift.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', NULL FROM q
