-- Q15 [Speciation & Isolation] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Speciation & Isolation', 'A field biologist studies two populations of birds and wants to determine whether they belong to the same species according to the biological species concept. Under this concept, the two populations represent a single species if, in nature, they:', '[{"label": "A", "text": "occupy the same geographic range"}, {"label": "B", "text": "share a close resemblance in body form"}, {"label": "C", "text": "interbreed and produce fertile, viable offspring"}, {"label": "D", "text": "descend from a recent common ancestor"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because the biological species concept defines a species by reproductive compatibility, not by appearance, location, or ancestry alone. The textbook states that ''A species is a group of individual organisms that interbreed and produce fertile, viable offspring'' and that ''one species is distinguished from another when, in nature, it is not possible for matings between individuals from each species to produce fertile offspring.'' Thus, the operational criterion under this concept is whether the two populations can interbreed in nature and yield offspring that are both viable and themselves capable of reproducing. (Choice A) is incorrect: occupying the same geographic range is not the criterion, because the textbook notes that allopatric (geographically separated) and sympatric (same-location) populations both exist, and geographic overlap does not by itself make two populations one species. (Choice B) is incorrect: morphological resemblance can be misleading, as the textbook illustrates with bald eagles and African fish eagles, which are ''similar in appearance'' yet ''are members of different species.'' (Choice C) is correct: interbreeding to produce fertile, viable offspring is exactly how the biological species concept defines a species. (Choice D) is incorrect: sharing a recent common ancestor describes phylogenetic relatedness (''all life has evolved and diversified from a common ancestor''), but the biological species concept keys on current reproductive compatibility, not on shared descent. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of the biological species concept.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 70)
  RETURNING id
)
