-- Q17 [Speciation & Isolation] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Speciation & Isolation', 'A horse and a donkey mate and produce a mule, which grows into a healthy adult but is itself unable to produce offspring. Which mechanism of reproductive isolation does the mule''s condition illustrate?', '[{"label": "A", "text": "A gametic barrier preventing fertilization"}, {"label": "B", "text": "Behavioral isolation preventing mating"}, {"label": "C", "text": "A postzygotic barrier causing hybrid inviability"}, {"label": "D", "text": "A postzygotic barrier causing hybrid sterility"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because the horse and donkey successfully mated and a zygote formed and developed into a viable adult mule, so any barrier here must act after zygote formation; the mule is healthy but sterile, which the textbook defines as hybrid sterility, a postzygotic barrier. OpenStax states that "A postzygotic barrier occurs after zygote formation. This includes organisms that don''t survive the embryonic stage and those that are born sterile," and that when "reproduction leads to hybrid birth and growth that is sterile... We call this hybrid sterility." Because fertilization and development clearly succeeded, every prezygotic explanation is excluded. (Choice A) A gametic barrier is a prezygotic barrier in which differences in gamete cells "prevent fertilization from taking place"; here fertilization succeeded and a zygote formed, so it acts at the wrong stage. (Choice B) Behavioral isolation is also prezygotic and "occurs when the presence or absence of a specific behavior prevents reproduction"; the animals did mate successfully, so no mating barrier operated. (Choice C) Hybrid inviability is correctly a postzygotic barrier, but it describes hybrids that "do not survive past the embryonic stages"; the mule is a viable, healthy adult, so the sterility-specific category fits instead. (Choice D) is correct: the mule is a viable but sterile hybrid, the textbook''s exact definition of hybrid sterility, a postzygotic barrier acting after the zygote forms. This is a Scientific Reasoning and Problem Solving question because you must apply the textbook''s definitions of prezygotic versus postzygotic barriers to a described scenario, using the facts that fertilization succeeded and the adult is viable to select the one barrier type consistent with both observations.', 'hard', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 150)
  RETURNING id
)
